def casepage(l,k,pre):
    c=DATA[l]['cases'][k]
    names={'tbank':choose(l,'Т-Банк','T-Bank'),'cody':'CODY','bpmn':'BPMN.space'}
    demo=bank_demo(l) if k=='tbank' else cody_demo(l) if k=='cody' else '<section class="case-demo process-demo" id="demo"><div id="process-demo-root"></div></section>'
    demo=demo.replace('class="case-demo bank-demo reveal"','class="case-demo bank-demo" id="demo"').replace('class="case-demo cody-demo reveal"','class="case-demo cody-demo" id="demo"')
    text=''.join(f'<section class="case-section"><h2>{e(s["title"])}</h2><p>{e(s["body"])}</p></section>' for s in c['sections'])
    nextk={'tbank':'cody','cody':'bpmn','bpmn':'tbank'}[k]
    return f'''<section class="case-hero"><a class="back-link" href="{link(pre,l)}#work">← {label(l,'Все проекты','All projects')}</a><div class="case-heading"><div><p class="section-label">{e(c['kicker'])}</p><h1>{names[k]}</h1><h2>{e(c['title'])}</h2></div><div><p class="case-summary">{e(c['summary'])}</p><a class="primary-button" href="#demo">{label(l,'Исследовать пример','Explore the example')} ↓</a></div></div><div class="case-meta"><div><span>{label(l,'Мой вклад','My contribution')}</span><p>{e(c['role'])}</p></div><div><span>{label(l,'Статус','Status')}</span><p>{e(c['status'])}</p></div><div><span>{label(l,'Инструменты','Tools')}</span><p>{' · '.join(map(e,c['stack'][:6]))}</p></div></div></section>{demo}<div class="case-reading">{text}<blockquote class="case-takeaway">{e(c['takeaway'])}</blockquote></div><a class="next-case" href="{link(pre,l,'work/'+nextk)}"><span class="section-label">{label(l,'Следующий проект','Next project')}</span><h2>{names[nextk]} {arrow()}</h2></a>'''

def audiencepage(l,p,pre):
    c=DATA[l]['audiences'][p]
    titles={'engineering':choose(l,'В вашу<br>инженерную команду.','For your<br>engineering team.'),'learning':choose(l,'Практика даёт<br>новые вопросы.','Practice brings<br>new questions.'),'collaborate':choose(l,'От общей идеи<br>к первому прототипу.','From a shared idea<br>to a first prototype.')}
    captions={'engineering':choose(l,'Опыт и решения','Experience & decisions'),'learning':choose(l,'Учёба и развитие','Learning & growth'),'collaborate':choose(l,'Сотрудничество','Collaboration')}
    destination='#contact' if p=='collaborate' else '#audience-work' if p=='learning' else pre+'cv/Timofei_Iakovlev_CV_'+l.upper()+'.pdf'
    intro=f'''<section class="audience-hero"><a class="back-link" href="{link(pre,l)}">← {label(l,'На главную','Back to home')}</a><p class="section-label">{captions[p]}</p><h1>{titles[p]}</h1><p class="audience-lead">{e(c['lead'])}</p><a class="primary-button" href="{destination}">{e(c['cta'])} {arrow()}</a></section>'''
    proofs='<section class="audience-proofs">'+''.join(f'<article><h2>{e(a["title"])}</h2><p>{e(a["body"])}</p></article>' for a in c['proofs'])+'</section>'
    extra=''
    if p=='learning':
        pairs=[('CODY',choose(l,'Как согласовать состояние нескольких систем?','How can multiple systems share consistent state?')),('BPMN.space',choose(l,'Где заканчивается генерация и начинается проверка?','Where should generation end and validation begin?')),(choose(l,'Т-Банк','T-Bank'),choose(l,'Как описать правило и проверить его последствия?','How do we express a rule and verify its consequences?'))]
        extra='<section class="learning-map"><h2>'+label(l,'Вопросы, с которыми иду дальше','Questions I want to explore')+'</h2><div>'+''.join(f'<div class="learning-row"><span>{name}</span><p>{question}</p></div>' for name,question in pairs)+'</div></section>'
    elif p=='engineering':
        extra=f'<section class="stack-section"><h2>{label(l,"Технологии в контексте работы","Tools in the context of work")}</h2><p>Python · SQL · PostgreSQL · Airflow · Kafka<br>TypeScript · React Native · Node.js · Docker</p><p class="small-copy">{label(l,"Москва. Рассматриваю переезд. Английский — B1 по самооценке.","Moscow. Open to relocation. English: self-assessed B1.")}</p></section>'
    else:
        extra=f'<section class="pilot"><h2>{label(l,"Начнём с одного процесса.","Start with one workflow.")}</h2><p>{label(l,"Выберем повторяющуюся операцию, согласуем границы и критерии готовности. Соберём первый прототип и проверим его на вашем сценарии.","Choose a repetitive task, agree on scope and acceptance criteria, then build a first prototype and test it against your scenario.")}</p><a class="text-link" href="mailto:timka6942@gmail.com?subject=Workflow%20pilot">{label(l,"Описать задачу","Describe the problem")} ↗</a></section>'
    order={'engineering':('tbank','cody'),'learning':('bpmn','cody'),'collaborate':('cody','bpmn')}[p]
    return intro+proofs+extra+f'<section id="audience-work" class="work-section"><div class="section-heading"><h2>{label(l,"Начните с этих проектов","Start with these projects")}</h2></div>{projects(l,pre,order)}</section>'

def emit(l,p='',root=False):
    f=Path('index.html') if root else hfile(l,p); pre=prefix(f)
    if p.startswith('work/'):
        k=p.split('/')[1];body=casepage(l,k,pre);title=DATA[l]['cases'][k]['title'];kind='case '+k
    elif p:body=audiencepage(l,p,pre);title=DATA[l]['audiences'][p]['title'];kind='audience '+p
    else:body=homepage(l,pre);title=choose(l,'Тимофей Яковлев — разработчик','Timofei Iakovlev — developer');kind='home'
    desc=choose(l,'Backend в Т-Банке. Личный прототип CODY. Командный BPMN.space. Проекты и инженерные решения Тимофея Яковлева.','Backend at T-Bank. CODY personal prototype. BPMN.space team project. Work and engineering decisions by Timofei Iakovlev.')
    canonical=ORIGIN+'/'+l+'/'+(p+'/' if p else '')
    page=f'''<!doctype html><html lang="{l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#08080a"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="noindex,nofollow"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="ru" href="{ORIGIN}/ru/{p+'/' if p else ''}"><link rel="alternate" hreflang="en" href="{ORIGIN}/en/{p+'/' if p else ''}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:image" content="{ORIGIN}/assets/social-cover.svg"><link rel="icon" type="image/svg+xml" href="{pre}assets/favicon.svg"><link rel="stylesheet" href="{pre}assets/style.css"><link rel="stylesheet" href="{pre}assets/personal.css"><script src="{pre}assets/motion.js" defer></script><script type="module" src="{pre}assets/app.js"></script></head><body id="top" class="{kind}" data-locale="{l}"><div class="reading-progress" aria-hidden="true"></div>{header(l,p,pre)}<main id="main">{body}</main>{footer(l,pre)}</body></html>'''
    dest=D/f;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(page)

for l in ('ru','en'):
    for p in ('','engineering','learning','collaborate','work/tbank','work/cody','work/bpmn'):emit(l,p)
emit('ru',root=True)
